"use strict";

const { URL } = require("url");

exports.describe = function describe(options) {
  const parsed = new URL(options.url);
  const policy = options.allowNetwork === true ? "requested" : "denied";
  const transport = options.adapter === "offline" ? "adapter" : "blocked";
  return `networkpolicy:${parsed.protocol.slice(0, -1)}:${policy}:${transport}`;
};
